{
  "decision": "revise",
  "reason": "The batch shows successful desklamp co-location and successful exact-target conditioning/placement, but also repeated skill-addressable failures: substituting a related non-target object for the requested one, prolonged search cycling without expanding to unexamined receptacle types or open surfaces, and issuing commands absent from the current admissible list.",
  "plan": {
    "goal": "Improve exact-target fidelity and search efficiency in non-desklamp retrieval, conditioning, and placement tasks while preserving the successful desklamp co-location behavior and the successful exact-target completion behavior already demonstrated.",
    "updates": [
      {
        "id": "u1",
        "text": "- When the task requests an exact object and that exact noun phrase has not been observed, do not acquire, clean, cool, heat, or place a different but related object as a substitute.\n- If a container holds only a non-matching object, leave it without manipulating that object and continue searching for the exact target.\n- Do not treat conditioning or placement of a non-target object as progress toward the task; only the exact requested object satisfies the goal.\n",
        "basis": [
          "G3",
          "P7:5",
          "P7:7",
          "P7:9",
          "P7:outcome"
        ]
      },
      {
        "id": "u2",
        "text": "- When the exact target has not been found after checking several receptacles of one type, expand the search to at least one still-unexamined receptacle of a different type before rechecking any location that was already opened or seen to lack the target.\n- Include visible open surfaces such as tables, countertops, shelves, and sidetables in the search, not only closed drawers or cabinets.\n- If an opened receptacle visibly lacks the target, leave it and choose a different uninspected candidate from the current admissible list; do not cycle back through the same already-inspected containers.\n",
        "basis": [
          "G2",
          "G3",
          "G4",
          "P3:8",
          "P3:9",
          "P6:3",
          "P6:4",
          "P6:5",
          "P8:14",
          "P8:15",
          "P8:16",
          "P10:6",
          "P10:7",
          "P10:8",
          "P10:32"
        ]
      },
      {
        "id": "u3",
        "text": "- Before committing to a navigation or manipulation command, verify that the command is present in the current admissible action list; if it is not, do not issue it.\n- When a desired navigation destination is absent but a direct action on that receptacle is listed, use the direct action if appropriate; otherwise choose a different admissible action that advances the search or task.\n",
        "basis": [
          "P1:4",
          "P6:20",
          "P6:21",
          "P8:5",
          "P8:6"
        ]
      }
    ],
    "checks": [
      {
        "id": "c1",
        "update_ids": [
          "u1"
        ],
        "question": "When the exact requested object is absent and a similar non-target object is available, does the Actor leave it unmanipulated and continue searching rather than cleaning or placing the substitute?"
      },
      {
        "id": "c2",
        "update_ids": [
          "u2"
        ],
        "question": "After several failed checks of one receptacle type, does the Actor inspect a different unexamined receptacle type or visible open surface instead of cycling among known-empty containers?"
      },
      {
        "id": "c3",
        "update_ids": [
          "u3"
        ],
        "question": "Does the Actor avoid commands absent from the current admissible list, and does it use an available direct manipulation action when the desired navigation destination is unavailable?"
      }
    ]
  }
}
